<script setup>
import {ref,computed,watch,onMounted,onUnmounted} from 'vue';
import {tr,locale,subjectValue} from './i18n.js';
import LanguageSwitch from './LanguageSwitch.vue';
import {LayoutDashboard,Users,CalendarDays,Wallet,Plus,ArrowUpRight,ChevronLeft,ChevronRight,Clock3,Sunset,Download,Check, X, Settings2,BookOpen,Info,SlidersHorizontal,Trash2} from 'lucide-vue-next';
import * as XLSX from 'xlsx';
import AvailabilityBoards from './AvailabilityBoards.vue';
import {seed,applySourceImport,applyConfirmedPayRules} from './import-data.js';
import {WEEKDAYS,cairoToday,weekday,clock,slotsFor,effectiveSlots,scheduleFor,saveDateSchedule,saveFixedSchedule,calculate,datesBetween,payModeLabel} from './payroll.js';
import {loadSharedState,saveSharedState} from './remote-state.js';
import {mergeLocalChanges} from './merge-local.js';
import {activeTeachers,deleteTeacher} from './teachers.js';
const today=cairoToday(), demoId='demo-zhang';
const blank=()=>({teachers:[],records:{},rules:{jodHalf:true}});
let initial=blank();try{const raw=localStorage.getItem('slot-salary-v1');if(raw)initial=JSON.parse(raw);}catch{}
initial.rules={jodHalf:true};
applySourceImport(initial);
applyConfirmedPayRules(initial);
try{localStorage.setItem('slot-salary-v1',JSON.stringify(initial));}catch{}
const data=ref(initial),page=ref('daily'),date=ref(today),query=ref(''),subject=ref('全部科目'),currency=ref('全部币种'),selected=ref(null),modal=ref(null),error=ref(''),notice=ref('');
const sync=ref({status:'connecting',revision:null,error:''}),migrationConflicts=ref([]);
let saveTimer,pollTimer,hydrating=false,saving=false,dirty=false;
const teachers=computed(()=>activeTeachers(data.value)),deleteName=ref('');
const nav=[{id:'daily',label:'每日工作台',icon:LayoutDashboard},{id:'teacherBoard',label:'老师课表',icon:CalendarDays},{id:'subjectBoard',label:'科目看板',icon:BookOpen},{id:'teachers',label:'老师档案',icon:Users},{id:'schedule',label:'排班管理',icon:CalendarDays},{id:'report',label:'工资汇总',icon:Wallet}];
const draft=ref({completed:0,exceptions:[],adjustments:[]}),teacherForm=ref({name:'',gender:'女',subject:'英语',rate:150,currency:'EGP',payMode:'slot'}),scheduleTeacher=ref(''),effective=ref(today),ranges=ref([]),exception=ref({kind:'add',start:'17:00',end:'18:00',reason:''}),adjustment=ref({amount:0,reason:''});
const scheduleMode=ref('week'),weekAnchor=ref(today),dateScheduleDay=ref(today),dateRanges=ref([]),dateReason=ref('');
const editingTeacher=ref(null),boardTeacher=ref(''),boardAnchor=ref(today);
const reportStart=ref(today.slice(0,7)+'-01'),reportEnd=ref(today),reportMode=ref('month');
watch(data,()=>{try{localStorage.setItem('slot-salary-v1',JSON.stringify(data.value));}catch{error.value='本机存储失败，请立即导出备份。';}if(sync.value.status==='connected'&&!hydrating){dirty=true;clearTimeout(saveTimer);saveTimer=setTimeout(saveShared,700);}}, {deep:true,flush:'sync'});
const money=(n,c='EGP')=>Number(n).toLocaleString('en-US',{minimumFractionDigits:c==='JOD'?3:2,maximumFractionDigits:c==='JOD'?3:2});
const subjectInput=computed({get:()=>tr(teacherForm.value.subject),set:v=>{teacherForm.value.subject=subjectValue(v);}});
const key=(id,d=date.value)=>`${id}:${d}`;
const allRows=computed(()=>teachers.value.map(t=>{const r=data.value.records[key(t.id)];try{return {teacher:t,record:r,pay:calculate(t,date.value,r||{},data.value.rules)};}catch(e){return {teacher:t,record:r,invalid:e.message,pay:{slots:effectiveSlots(t,date.value,r?.exceptions||[]),completed:r?.completed||0,total:0,lesson:0,compensation:0,bonus:0}};}}));
const rows=computed(()=>allRows.value.filter(r=>(!query.value||r.teacher.name.includes(query.value))&&(subject.value==='全部科目'||r.teacher.subject===subject.value)&&(currency.value==='全部币种'||r.teacher.currency===currency.value)));
const subjects=computed(()=>[...new Set(teachers.value.map(t=>t.subject))]);
const totals=computed(()=>{const r={EGP:0,JOD:0,slots:0,completed:0,entered:0};for(const x of allRows.value){r.slots+=x.pay.slots.length;if(x.record&&!x.invalid){r[x.teacher.currency]+=x.pay.total;r.completed+=x.pay.completed;r.entered++;}}return r;});
const livePay=computed(()=>{if(!selected.value)return null;try{return calculate(selected.value,date.value,draft.value,data.value.rules);}catch{return null;}});
const report=computed(()=>{try{const ds=datesBetween(reportStart.value,reportEnd.value);return data.value.teachers.map(t=>{const items=ds.flatMap(d=>{const r=data.value.records[key(t.id,d)];if(!r)return [];try{return [{date:d,...calculate(t,d,r,data.value.rules)}];}catch{return [];}});return {teacher:t,items,days:items.length,...['lesson','compensation','hourlyPay','paidHours','bonus','adjustments','total','completed'].reduce((a,k)=>(a[k]=items.reduce((s,x)=>s+x[k],0),a),{})};});}catch{return [];}});
function toast(s){notice.value=s;setTimeout(()=>notice.value='',3500);}
async function connectShared(){
 clearTimeout(saveTimer);
 sync.value={status:'connecting',revision:null,error:''};
 const loaded=await loadSharedState();
 let migrated=false;try{migrated=localStorage.getItem('slot-salary-public-migrated')==='yes';}catch{}
 if(loaded.status===200){
  if(!migrated){
   try{localStorage.setItem('slot-salary-pre-public-backup',JSON.stringify(data.value));}catch{sync.value={status:'conflict',revision:loaded.revision,error:'无法保留此前本机数据，请先下载备份后重试。'};return;}
   const merged=mergeLocalChanges(data.value,loaded.data);migrationConflicts.value=merged.conflicts;
   if(merged.changed){const saved=await saveSharedState(merged.data,loaded.revision);if(saved.status!==200){sync.value={status:'conflict',revision:loaded.revision,error:'首次合并未完成，本机数据已保留，请重试连接。'};return;}loaded.data=merged.data;loaded.revision=saved.revision;}
  }
  hydrating=true;data.value=loaded.data;hydrating=false;dirty=false;
  sync.value={status:'connected',revision:loaded.revision,error:''};
  try{localStorage.setItem('slot-salary-public-migrated','yes');localStorage.setItem('slot-salary-migration-conflicts',JSON.stringify(migrationConflicts.value));}catch{}
  return;
 }
 if(loaded.status===404){const saved=await saveSharedState(JSON.parse(JSON.stringify(data.value)),null);if(saved.status===201){sync.value={status:'connected',revision:saved.revision,error:''};try{localStorage.setItem('slot-salary-public-migrated','yes');}catch{}return;}if(saved.status===409)return connectShared();sync.value={status:'conflict',revision:null,error:saved.error||'初始化共享数据失败。'};return;}
 sync.value={status:'conflict',revision:null,error:loaded.error||'无法连接共享数据。'};
}
async function saveShared(){
 if(sync.value.status!=='connected'||saving)return;
 saving=true;dirty=false;
 const saved=await saveSharedState(JSON.parse(JSON.stringify(data.value)),sync.value.revision);
 saving=false;
 if(saved.status===200){sync.value={status:'connected',revision:saved.revision,error:''};if(dirty)saveTimer=setTimeout(saveShared,50);return;}
 sync.value={status:'conflict',revision:sync.value.revision,error:saved.error||'同步失败。请下载本机备份后重新加载共享数据。'};
}
async function reloadShared(){
 if(dirty||sync.value.status==='conflict'){backup();try{localStorage.setItem('slot-salary-unsynced-backup',JSON.stringify(data.value));}catch{}}
 await connectShared();
}
function downloadPreviousLocal(){const raw=localStorage.getItem('slot-salary-pre-public-backup');if(!raw)return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([raw],{type:'application/json'}));a.download='slot-salary-before-shared.json';a.click();URL.revokeObjectURL(a.href);}
function exportMigrationConflicts(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(migrationConflicts.value,null,2)],{type:'application/json'}));a.download='slot-salary-migration-conflicts.json';a.click();URL.revokeObjectURL(a.href);}
onMounted(()=>{try{migrationConflicts.value=JSON.parse(localStorage.getItem('slot-salary-migration-conflicts')||'[]');}catch{}connectShared();pollTimer=setInterval(async()=>{if(sync.value.status!=='connected')return;if(saving||dirty||modal.value)return;const loaded=await loadSharedState();if(loaded.status===200&&loaded.revision!==sync.value.revision&&!saving&&!dirty&&!modal.value){hydrating=true;data.value=loaded.data;sync.value.revision=loaded.revision;hydrating=false;}},10000);});
onUnmounted(()=>{clearInterval(pollTimer);clearTimeout(saveTimer);});
function run(fn){error.value='';try{if(sync.value.status!=='connected')throw Error(locale.value==='en'?'Shared data is not connected. Changes cannot be saved yet.':'尚未连接共享数据，暂时不能保存修改。');fn();}catch(e){error.value=e.message;}}
function shiftDay(n){const d=new Date(date.value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);date.value=d.toISOString().slice(0,10);}
function openDaily(t){if(!Number.isFinite(t.rate)||!t.currency){openTeacher(t);error.value='请先补充时薪和币种，再录入完课及工资。';return;}selected.value=t;draft.value=structuredClone(data.value.records[key(t.id)]?JSON.parse(JSON.stringify(data.value.records[key(t.id)])):{completed:0,exceptions:[],adjustments:[]});error.value='';modal.value='daily';}
function saveDaily(){run(()=>{if(!livePay.value)throw Error('请检查完课数量，不得超过有效 slot 数。');if(draft.value.completed===''||draft.value.completed===null)throw Error('请填写完课数，未完课请填 0。');data.value.records[key(selected.value.id)]={...JSON.parse(JSON.stringify(draft.value)),completed:Number(draft.value.completed)};modal.value=null;toast('每日记录已保存到本机');});}
function openTeacher(t=null){editingTeacher.value=t?.id||null;teacherForm.value=t?{name:t.name,gender:t.gender,subject:t.subject,rate:t.rate??'',currency:t.currency||'',payMode:t.payMode||'slot'}:{name:'',gender:'未提供',subject:'英语',rate:'',currency:'',payMode:'slot'};error.value='';modal.value='teacher';}
function requestDelete(){deleteName.value='';error.value='';modal.value='deleteTeacher';}
function confirmDelete(){run(()=>{const t=deleteTeacher(data.value,editingTeacher.value,deleteName.value);if(boardTeacher.value===t.id)boardTeacher.value='';modal.value=null;toast(locale.value==='en'?'Teacher deleted. Historical payroll records are retained.':'老师已删除，历史工资记录已保留。');});}
function showTeacher(id){boardTeacher.value=id;page.value='teacherBoard';}
function saveTeacher(){run(()=>{const f=teacherForm.value;if(!f.name.trim()||!f.subject.trim()||!Number.isFinite(Number(f.rate))||Number(f.rate)<=0||!['EGP','JOD'].includes(f.currency))throw Error('请填写姓名、科目、大于 0 的时薪和币种');const fields={...f,name:f.name.trim(),subject:f.subject.trim(),rate:Number(f.rate)};if(editingTeacher.value){const t=data.value.teachers.find(t=>t.id===editingTeacher.value);Object.assign(t,fields);}else{data.value.teachers.push({...fields,id:crypto.randomUUID(),schedules:[]});}modal.value=null;toast(editingTeacher.value?'老师资料已更新，排班保持不变':'老师已添加，接下来可设置固定排班');});}
function openSchedule(t){scheduleTeacher.value=t.id;effective.value=today;ranges.value=JSON.parse(JSON.stringify([...t.schedules].sort((a,b)=>b.effective.localeCompare(a.effective))[0]?.ranges||[]));modal.value='schedule';error.value='';}
function saveSchedule(){run(()=>{const t=data.value.teachers.find(x=>x.id===scheduleTeacher.value);saveFixedSchedule(t,effective.value,ranges.value,Object.keys(data.value.records).filter(k=>k.startsWith(t.id+':')).map(k=>k.slice(t.id.length+1)));modal.value=null;toast('固定排班已保存，核对前的版本已保留');});}
const addDays=(date,n)=>{const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
const weekDates=computed(()=>{const anchor=weekAnchor.value||today;const start=addDays(anchor,-weekday(anchor));return datesBetween(start,addDays(start,6));});
function openDateSchedule(t,d){scheduleTeacher.value=t.id;dateScheduleDay.value=d;dateRanges.value=JSON.parse(JSON.stringify(scheduleFor(t,d)));dateReason.value=t.dateSchedules?.[d]?.reason||'';error.value='';modal.value='dateSchedule';}
function copyLastWeek(){const t=data.value.teachers.find(t=>t.id===scheduleTeacher.value);dateRanges.value=JSON.parse(JSON.stringify(scheduleFor(t,addDays(dateScheduleDay.value,-7))));toast('已复制上周同日排班，请检查后保存');}
function saveOneDate(){run(()=>{const t=data.value.teachers.find(t=>t.id===scheduleTeacher.value);saveDateSchedule(t,dateScheduleDay.value,dateRanges.value,dateReason.value,!!data.value.records[key(t.id,dateScheduleDay.value)]);modal.value=null;toast('指定日期排班已保存，仅影响当天');});}
function restoreFixed(){run(()=>{const t=data.value.teachers.find(t=>t.id===scheduleTeacher.value);if(data.value.records[key(t.id,dateScheduleDay.value)])throw Error('该日期已录入工资，请通过每日记录的异常调整处理');delete t.dateSchedules[dateScheduleDay.value];modal.value=null;toast('当天已恢复使用固定排班');});}
function addException(){run(()=>{if(!exception.value.reason.trim())throw Error('请填写异常原因');slotsFor([exception.value]);const next=JSON.parse(JSON.stringify(draft.value));next.exceptions.push({...exception.value});calculate(selected.value,date.value,next,data.value.rules);draft.value=next;exception.value.reason='';});}
function addAdjustment(){run(()=>{if(!adjustment.value.reason.trim()||!Number.isFinite(Number(adjustment.value.amount))||Number(adjustment.value.amount)===0)throw Error('请填写非零调整金额和原因');draft.value.adjustments.push({amount:Number(adjustment.value.amount),reason:adjustment.value.reason});adjustment.value={amount:0,reason:''};});}
function sample(){if(data.value.teachers.length)return;data.value.teachers=[{id:demoId,name:'张老师',gender:'女',subject:'英语',rate:150,currency:'EGP',schedules:[{effective:'2026-01-01',ranges:[{day:0,start:'16:00',end:'21:00'}]}]}];data.value.records[`${demoId}:2026-10-18`]={completed:4,exceptions:[],adjustments:[]};date.value='2026-10-18';toast('已载入你提供的示例，可修改或清除');}
function period(mode){reportMode.value=mode;const d=new Date(date.value+'T12:00:00Z');if(mode==='week'){d.setUTCDate(d.getUTCDate()-d.getUTCDay());reportStart.value=d.toISOString().slice(0,10);d.setUTCDate(d.getUTCDate()+6);reportEnd.value=d.toISOString().slice(0,10);}else if(mode==='month'){reportStart.value=date.value.slice(0,7)+'-01';d.setUTCMonth(d.getUTCMonth()+1,0);reportEnd.value=d.toISOString().slice(0,10);}}
function exportExcel(){run(()=>{datesBetween(reportStart.value,reportEnd.value);const wb=XLSX.utils.book_new();const summary=report.value.map(r=>({'老师':r.teacher.name,'科目':r.teacher.subject,'币种':r.teacher.currency,'计薪方式':payModeLabel(r.teacher.payMode),'计薪小时':r.paidHours,'时长工资':r.hourlyPay,'已录入天数':r.days,'完课数':r.completed,'完课工资':r.lesson,'半薪补偿':r.compensation,'晚间奖励':r.bonus,'人工调整':r.adjustments,'合计':r.total}));const details=report.value.flatMap(r=>r.items.map(x=>({'日期':x.date,'老师':r.teacher.name,'币种':r.teacher.currency,'排班来源':r.teacher.dateSchedules?.[x.date]?'指定日期排班':'固定模板','排班备注':r.teacher.dateSchedules?.[x.date]?.reason||'','有效slot':x.slots.length,'完课':x.completed,'计薪方式':payModeLabel(x.payMode),'计薪小时':x.paidHours,'时长工资':x.hourlyPay,'半薪slot':x.halfPaySlots,'奖励小时':x.bonusHours,'完课工资':x.lesson,'半薪补偿':x.compensation,'晚间奖励':x.bonus,'人工调整':x.adjustments,'总计':x.total,'异常原因':(data.value.records[key(r.teacher.id,x.date)].exceptions||[]).map(e=>`${e.kind} ${e.start}–${e.end} ${e.reason}`).join('；'),'调整原因':(data.value.records[key(r.teacher.id,x.date)].adjustments||[]).map(a=>`${a.amount} ${a.reason}`).join('；')})));for(const [name,items]of [['工资汇总',summary],['每日明细',details]]){const ws=XLSX.utils.json_to_sheet(items.map(row=>Object.fromEntries(Object.entries(row).map(([key,value])=>[tr(key),['科目','计薪方式','排班来源'].includes(key)?tr(value):value]))));ws['!cols']=Object.keys(items[0]||{}).map(()=>({wch:18}));XLSX.utils.book_append_sheet(wb,ws,tr(name));}XLSX.writeFile(wb,`${tr('工资')}_${reportStart.value}_${reportEnd.value}.xlsx`);});}
function backup(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data.value,null,2)],{type:'application/json'}));a.download=`${tr('课时簿备份')}_${today}.json`;a.click();URL.revokeObjectURL(a.href);}
function clearDemo(){if(data.value.teachers.length!==1||data.value.teachers[0].id!==demoId)return;data.value=blank();toast('示例数据已清除');}
const kindName=k=>({add:'临时加时',leave:'请假',late:'异常扣除（原迟到记录）',other:'异常扣除 slot',absent:'老师缺席'}[k]);
</script>

<template>
<div class="app-shell">
  <aside class="sidebar">
    <a class="brand" href="#" @click.prevent="page='daily'"><span class="brand-icon"><BookOpen :size="23"/></span><span>{{ tr("课时簿") }}<small>SLOT & SALARY</small></span></a>
    <div class="workspace-label">{{ tr("教务管理工作空间") }}</div>
    <nav><button v-for="n in nav" :key="n.id" :class="{active:page===n.id}" @click="page=n.id"><component :is="n.icon" :size="19"/>{{ tr(n.label) }}<span v-if="page===n.id" class="nav-dot"></span></button></nav>
    <div class="sidebar-note"><div class="note-icon"><Clock3 :size="19"/></div><strong>{{ tr("把时间，算清楚。") }}</strong><p>{{ tr("从每个 slot 到每份工资，") }}<br>{{ tr("让教务工作井井有条。") }}</p><span>AFRICA / CAIRO</span></div>
    <button class="settings-link" @click="modal='settings';error='' "><Settings2 :size="18"/>{{ tr("规则与数据") }}</button>
    <div class="profile"><span class="avatar">{{ tr("运") }}</span><div><strong>{{ tr("教务运营") }}</strong><small>{{ tr("本机预览工作空间") }}</small></div><span class="online"></span></div>
  </aside>
  <div class="main-shell">
    <header class="topbar"><div>{{ tr("工作空间 ") }}<span>/</span> <strong>{{ tr(nav.find(n=>n.id===page)?.label) }}</strong></div><div class="top-right"><button class="sync-status" :class="sync.status" @click="reloadShared"><span></span>{{ tr(sync.status==='connected'?'已连接共享数据':sync.status==='connecting'?'正在连接数据…':'正在连接数据…') }}</button><span class="divider"></span><Clock3 :size="15"/>{{ tr("开罗时间 ") }}<span class="top-date">{{ tr(today) }}</span></div><LanguageSwitch/></header>
    <main>
      <div v-if="migrationConflicts.length" class="error">{{locale==='en'?'Some previous local changes conflict with shared data and need review. Both versions have been preserved.':'此前本机修改与共享数据有冲突，已保留双方内容，请下载明细核对。'}}<button @click="exportMigrationConflicts">{{locale==='en'?'Download conflicts':'下载冲突明细'}}</button></div>
      <div v-if="sync.status==='connected'" class="info-bar">{{locale==='en'?'Everyone using this URL shares the same Supabase data. Updates appear within about 10 seconds when no editing form is open.':'此网址已直接连接同一套 Supabase 数据，无需访问码。未打开编辑表单时，约每 10 秒自动获取他人的更新。'}}</div>
      <div v-if="sync.error" class="error">{{tr(sync.error)}} <button @click="backup">{{tr('下载数据备份')}}</button> <button @click="reloadShared">{{tr('重新加载共享数据')}}</button></div>
      <div class="preview-banner" :class="{connected:sync.status==='connected'}"><Info :size="16"/><span>{{locale==='en'?(sync.status==='connected'?'Shared data connected. Saved changes are synchronized automatically.':'Connecting to shared data. Please wait before editing.'):(sync.status==='connected'?'共享数据已连接，保存的修改会自动同步。':'正在连接共享数据，请连接成功后再编辑。')}}</span><button @click="reloadShared">{{tr('重新加载共享数据')}}</button><button @click="backup">{{tr('下载数据备份')}}</button><button @click="downloadPreviousLocal">{{locale==='en'?'Previous local backup':'下载此前本机数据'}}</button></div>
      <div class="page-heading"><div><div class="eyebrow">{{ tr(page==='daily'?'YOUR DAILY OVERVIEW':page==='teacherBoard'?'TEACHER AVAILABILITY':page==='subjectBoard'?'SUBJECT AVAILABILITY':page==='teachers'?'TEACHER DIRECTORY':page==='schedule'?'WEEKLY AVAILABILITY':'PAYROLL OVERVIEW') }}</div><h1>{{ tr(nav.find(n=>n.id===page)?.label) }}</h1><p>{{ tr(page==='daily'?tr('排班、完课与工资，每一天都清清楚楚。'):page==='teacherBoard'?tr('选择一位老师，查看这一周每天的可用时间。'):page==='subjectBoard'?tr('按科目和半小时时间查询，快速找到有哪些老师有空。'):page==='teachers'?tr('管理老师信息与时薪，支持 EGP 和 JOD。'):page==='schedule'?tr('周日到周四以固定排班为主，周五、周六可按每周实际日期安排。'):tr('按周、按月或自选日期，查看每份工资的构成。')) }}</p></div><button v-if="page==='daily'||page==='teachers'" class="primary" @click="openTeacher()"><Plus :size="17"/>{{ tr("添加老师") }}</button><button v-if="page==='report'" class="primary" @click="exportExcel"><Download :size="17"/>{{ tr("导出 Excel") }}</button></div>
      <AvailabilityBoards v-if="page==='teacherBoard'||page==='subjectBoard'" :key="page" :mode="page==='teacherBoard'?'teacher':'subject'" :teachers="teachers" :records="data.records" :initial-teacher="boardTeacher" :initial-date="boardAnchor" @date="boardAnchor=$event" @edit-fixed="openSchedule" @edit-date="openDateSchedule" @teacher="showTeacher"/>
      <template v-if="page==='daily'">
        <div class="date-strip"><div class="date-picker"><button :aria-label='tr("前一天")' @click="shiftDay(-1)"><ChevronLeft :size="18"/></button><CalendarDays :size="17"/><input type="date" v-model="date"/><span>{{ tr(WEEKDAYS[weekday(date)]) }}</span><button :aria-label='tr("后一天")' @click="shiftDay(1)"><ChevronRight :size="18"/></button></div><button class="today-button" @click="date=today">{{ tr("今天") }}</button><span class="strip-note">{{ tr("每日数据按开罗当地日期统计") }}</span></div>
        <div class="stats-grid">
          <article class="stat-card"><div class="stat-label">{{ tr("开放 slot ") }}<span class="stat-icon mint"><CalendarDays :size="19"/></span></div><div class="stat-number">{{ tr(totals.slots) }}<small>{{ tr("个") }}</small></div><div class="stat-foot">{{ tr(totals.slots/2) }}{{ tr(" 小时可用时间 ") }}<span>{{ tr("30 分钟 / slot") }}</span></div></article>
          <article class="stat-card"><div class="stat-label">{{ tr("已录入完课 ") }}<span class="stat-icon blue"><Check :size="19"/></span></div><div class="stat-number">{{ tr(totals.completed) }}<small>{{ tr("节") }}</small></div><div class="stat-foot">{{ tr(totals.entered) }} / {{ tr(teachers.length) }}{{ tr(" 位老师已录入 ") }}<span>{{ tr("25 分钟 / 节") }}</span></div></article>
          <article class="stat-card featured"><div class="stat-label">{{ tr("当日工资 · EGP ") }}<span class="stat-icon green"><Wallet :size="19"/></span></div><div class="stat-number">{{ tr(money(totals.EGP)) }}<small>EGP</small></div><div class="stat-foot">{{ tr("基础工资 + 奖励 + 调整 ") }}<span>{{ tr("仅统计已录入") }}</span></div></article>
          <article class="stat-card"><div class="stat-label">{{ tr("当日工资 · JOD ") }}<span class="stat-icon amber"><Wallet :size="19"/></span></div><div class="stat-number">{{ tr(money(totals.JOD,'JOD')) }}<small>JOD</small></div><div class="stat-foot">{{ tr("独立核算，不与 EGP 合并 ") }}<span>{{ tr("无晚间奖励") }}</span></div></article>
        </div>
        <section class="panel daily-panel"><div class="panel-title"><h2>{{ tr("老师每日记录 ") }}<span>{{ tr(rows.length) }}</span></h2><div class="legend"><i></i>{{ tr("每日更新完课数量，自动核算工资") }}</div></div><div class="filters"><label class="search"><Users :size="17"/><input :placeholder='tr("搜索老师姓名…")' v-model="query"/></label><select v-model="subject"><option :value='"全部科目"'>{{ tr("全部科目") }}</option><option :value="s" v-for="s in subjects">{{ tr(s) }}</option></select><select v-model="currency"><option :value='"全部币种"'>{{ tr("全部币种") }}</option><option :value='"EGP"'>EGP</option><option :value='"JOD"'>JOD</option></select><span class="filter-end"><SlidersHorizontal :size="15"/>{{ tr(date) }}</span></div>
        <div class="table-scroll"><table><thead><tr><th>{{ tr("老师 / 科目") }}</th><th>{{ tr("开放时间") }}</th><th>{{ tr("有效 slot") }}</th><th>{{ tr("完课 / 计薪方式") }}</th><th>{{ tr("晚间奖励") }}</th><th class="right">{{ tr("当日工资") }}</th><th></th></tr></thead><tbody><tr v-for="r in rows" :key="r.teacher.id"><td><div class="teacher-cell"><span class="teacher-avatar">{{ tr(r.teacher.name.slice(0,1)) }}</span><div><strong>{{ r.teacher.name }}</strong><small>{{ tr(r.teacher.subject) }} <b>·</b> {{ tr(r.teacher.rate&&r.teacher.currency?money(r.teacher.rate,r.teacher.currency)+' '+r.teacher.currency+tr(' / 小时'):tr('时薪 / 币种待补充')) }}</small><small>{{ tr(payModeLabel(r.teacher.payMode)) }}</small></div></div></td><td><div v-for="(s,i) in scheduleFor(r.teacher,date)" :key="i" class="time-range">{{ tr(s.start) }} – {{ tr(s.end) }}</div><span v-if="!scheduleFor(r.teacher,date).length" class="muted">{{ tr("当天无排班") }}</span><small class="schedule-source">{{ tr(r.teacher.dateSchedules?.[date]?tr('指定日期排班'):tr('每周固定排班')) }}</small><small v-if="r.record?.exceptions.length" class="exception-tag">{{ tr(r.record.exceptions.length) }}{{ tr(" 项时间调整") }}</small></td><td><strong>{{ tr(r.pay.slots.length) }}</strong><span class="muted">{{ tr(" 个") }}</span></td><td><template v-if="r.record"><span class="completed-number">{{ tr(r.pay.completed) }}</span><span class="muted" v-if="r.teacher.payMode!=='hourly'"> / {{ tr(r.pay.remaining) }}{{ tr(" 半薪") }}</span><small v-else class="schedule-source">{{ tr("按开放时长 ") }}{{ tr(r.pay.paidHours) }}{{ tr(" 小时") }}</small></template><span v-else class="badge">{{ tr("待录入") }}</span></td><td><span v-if="r.record&&r.pay.bonus" class="bonus-value">+ {{ tr(money(r.pay.bonus)) }}<small>EGP</small></span><span v-else class="muted">—</span></td><td class="right"><span v-if="r.invalid" class="badge">{{ tr("资料待补充") }}</span><strong class="salary" v-else-if="r.record">{{ tr(money(r.pay.total,r.teacher.currency)) }}<small>{{ tr(r.teacher.currency) }}</small></strong><span v-else class="muted">{{ tr("待录入") }}</span></td><td><button class="text-button" @click="openDaily(r.teacher)">{{ tr(r.invalid?tr('补充资料'):r.record?tr('查看 / 编辑'):tr('录入记录')) }}<ChevronRight :size="14"/></button></td></tr></tbody></table></div>
        <div v-if="!rows.length" class="empty-state"><div class="empty-symbol"><CalendarDays :size="30"/></div><h3>{{ tr(teachers.length?tr('没有匹配的老师'):tr('从第一位老师开始')) }}</h3><p>{{ tr(teachers.length?tr('试试调整筛选条件。'):tr('添加老师与每周排班，就可以开始记录完课和核算工资。')) }}</p><button v-if="!teachers.length" class="secondary" @click="sample">{{ tr("载入张老师的 925 EGP 示例 ") }}<ArrowUpRight :size="15"/></button></div><div class="table-footer"><span>{{ tr("共 ") }}{{ tr(rows.length) }}{{ tr(" 位老师 · ") }}{{ tr(allRows.filter(r=>r.record).length) }}{{ tr(" 位已录入") }}</span><span>{{ tr("所有金额以对应货币独立核算") }}</span></div></section>
        <div class="bottom-grid"><section class="explanation"><span class="explain-icon"><Wallet :size="21"/></span><div><h3>{{ tr("每一份工资，都有据可查") }}</h3><p>{{ tr("按 slot 计薪区分完课与半薪补偿；按开放时长计薪按有效时长全额支付。请假移除的时间不计薪。") }}</p><button @click="modal='settings'">{{ tr("查看完整计算规则 ") }}<ArrowUpRight :size="13"/></button></div></section><section class="evening-note"><Sunset :size="27"/><div><h3>{{ tr("晚间奖励 ") }}<span>{{ tr("EGP · 按 slot 计薪") }}</span></h3><p>{{ tr("17:00–21:00 · 每段连续满 1 小时奖励 100 EGP") }}</p><small>{{ tr("独立的半小时不计奖励，不跨时间段累计。") }}</small></div>
</section></div>
      </template>
      <template v-if="page==='teachers'"><section class="panel import-summary"><div><div class="eyebrow">EXCEL IMPORT</div><h2>{{ tr("slot 总表已导入 · ") }}{{ tr(seed.teachers.length) }}{{ tr(" 位老师") }}</h2><p>{{ seed.source }}{{ tr(" / slot · 固定排班从 ") }}{{ tr(seed.effective) }}{{ tr(" 起生效") }}</p></div><button class="secondary" @click="modal='importReview';error=''">{{ tr("查看导入核对明细") }}</button><div class="import-counts"><span v-for="s in ['英语','数学','阿拉伯语']">{{ tr(s) }} {{ tr(seed.teachers.filter(t=>t.subject===s).length) }}{{ tr(" 位") }}</span><span>{{ tr(seed.cells.reduce((n,c)=>n+c.names.length,0)) }}{{ tr(" 个老师 slot / 周") }}</span><span>{{ tr("未填写性别、时薪或币种的老师请逐一补充") }}</span></div></section><section class="panel"><div class="panel-title"><h2>{{ tr("全部老师 ") }}<span>{{ tr(teachers.length) }}</span></h2></div><div class="teacher-grid"><article v-for="t in teachers" class="teacher-card"><span class="teacher-avatar">{{ tr(t.name.slice(0,1)) }}</span><h3>{{ t.name }}</h3><p>{{ tr(t.gender) }} · {{ tr(t.subject) }}</p><strong v-if="t.rate&&t.currency">{{ tr(money(t.rate,t.currency)) }} <small>{{ tr(t.currency) }}{{ tr(" / 小时") }}</small></strong><span v-else class="badge">{{ tr("时薪 / 币种待补充") }}</span><p class="pay-mode-note">{{ tr(payModeLabel(t.payMode)) }}{{ tr(t.payMode==='hourly'?tr(' · 无晚间奖励'):'') }}</p><div v-if="t.source" class="source-note">{{ tr("来源：slot!") }}{{ tr(t.source.cells.slice(0,3).join('、')) }}{{ tr(" 等 ") }}{{ tr(t.source.cells.length) }}{{ tr(" 格") }}</div><button class="text-button" @click="openTeacher(t)">{{ tr("编辑老师资料 ") }}<ChevronRight :size="14"/></button><div class="teacher-card-footer"><span>{{ tr(t.schedules.length?tr('已设置固定排班'):tr('尚未设置排班')) }}</span><button class="text-button" @click="openSchedule(t)">{{ tr("设置排班 ") }}<ChevronRight :size="14"/></button></div></article></div><div v-if="!teachers.length" class="empty-state"><Users :size="32"/><h3>{{ tr("还没有老师") }}</h3><p>{{ tr("点击右上角“添加老师”建立老师档案。") }}</p></div></section></template>
      <template v-if="page==='schedule'">
        <div class="schedule-toolbar"><div class="segmented"><button :class="{chosen:scheduleMode==='week'}" @click="scheduleMode='week'">{{ tr("本周实际排班") }}</button><button :class="{chosen:scheduleMode==='fixed'}" @click="scheduleMode='fixed'">{{ tr("每周固定模板") }}</button></div><div v-if="scheduleMode==='week'" class="date-picker"><button :aria-label='tr("上一周")' @click="weekAnchor=addDays(weekAnchor,-7)"><ChevronLeft :size="17"/></button><input :aria-label='tr("选择排班周")' type="date" v-model="weekAnchor"/><button :aria-label='tr("下一周")' @click="weekAnchor=addDays(weekAnchor,7)"><ChevronRight :size="17"/></button></div><button v-if="scheduleMode==='week'" class="secondary" @click="weekAnchor=today">{{ tr("本周") }}</button></div>
        <div class="info-bar"><Info :size="17"/><span v-if="scheduleMode==='week'">{{ tr(weekDates[0]) }}{{ tr(" 至 ") }}{{ tr(weekDates[6]) }}{{ tr(" · 指定日期排班优先于固定模板，仅影响当天。可设置当天不开放；周五、周六也支持固定排班。") }}</span><span v-else>{{ tr("固定模板按生效日期保留历史版本，七天均可设置。每周变化的周五、周六，请在“本周实际排班”中设置。") }}</span></div>
        <section v-for="t in teachers" :key="t.id" class="panel schedule-panel"><div class="panel-title"><h2>{{ t.name }} <span>{{ tr(t.subject) }}</span></h2><button class="secondary" @click="openSchedule(t)"><Plus :size="15"/>{{ tr("修改固定模板") }}</button></div>
          <div v-if="scheduleMode==='week'" class="week-grid actual-week"><div v-for="(d,i) in weekDates" :key="d" class="weekday" :class="{weekend:i>=5,overridden:t.dateSchedules?.[d]}"><strong>{{ tr(WEEKDAYS[i]) }} <small>{{ tr(d.slice(5)) }}</small></strong><div class="day-source">{{ tr(t.dateSchedules?.[d]?tr('指定日期'):i>=5?tr('周末 · 可临时安排'):tr('固定模板')) }}</div><span v-for="(r,j) in scheduleFor(t,d)" :key="j">{{ tr(r.start) }}–{{ tr(r.end) }}</span><small v-if="!scheduleFor(t,d).length">{{ tr(t.dateSchedules?.[d]?tr('当天不开放'):tr('暂未排班')) }}</small><p v-if="t.dateSchedules?.[d]?.reason" class="day-reason">{{ tr(t.dateSchedules[d].reason) }}</p><button class="text-button" @click="openDateSchedule(t,d)">{{ tr(t.dateSchedules?.[d]?tr('编辑当天'):tr('设置当天')) }}<Plus :size="12"/></button></div></div>
          <div v-else class="week-grid"><div v-for="(day,d) in WEEKDAYS" class="weekday" :class="{weekend:d>=5}"><strong>{{ tr(day) }}</strong><span v-for="r in [...t.schedules].sort((a,b)=>b.effective.localeCompare(a.effective))[0]?.ranges.filter(r=>Number(r.day)===d)">{{ tr(r.start) }}–{{ tr(r.end) }}</span><small v-if="![...t.schedules].sort((a,b)=>b.effective.localeCompare(a.effective))[0]?.ranges.some(r=>Number(r.day)===d)">{{ tr("无固定排班") }}</small></div></div>
          <div class="table-footer"><span>{{ tr(scheduleMode==='week'?tr('展示当天采用的基础排班；请假、加时在每日记录中查看。'):tr('展示最新固定模板，指定日期安排单独保存。')) }}</span><span v-if="scheduleMode==='fixed'" v-for="s in t.schedules">{{ tr(s.effective) }}{{ tr(" 起生效") }}</span></div>
        </section><div v-if="!teachers.length" class="panel empty-state"><CalendarDays :size="32"/><h3>{{ tr("先添加一位老师") }}</h3><p>{{ tr("之后可设置固定模板和周五、周六的指定日期排班。") }}</p></div>
      </template>
      <template v-if="page==='report'"><div class="report-toolbar"><div class="segmented"><button v-for="m in [{id:'week',name:'按周'},{id:'month',name:'按月'},{id:'custom',name:'自选日期'}]" :class="{chosen:reportMode===m.id}" @click="period(m.id)">{{ tr(m.name) }}</button></div><input type="date" v-model="reportStart"/><span>{{ tr("至") }}</span><input type="date" v-model="reportEnd"/></div><div v-if="reportStart>reportEnd" class="error">{{ tr("结束日期不能早于开始日期") }}</div><div class="report-cards"><article class="stat-card" v-for="c in ['EGP','JOD']"><div class="stat-label">{{ tr("期间工资合计 · ") }}{{ tr(c) }}</div><div class="stat-number">{{ tr(money(report.filter(r=>r.teacher.currency===c).reduce((s,r)=>s+r.total,0),c)) }}<small>{{ tr(c) }}</small></div><p class="muted">{{ tr("仅汇总已录入的每日记录") }}</p></article></div><section class="panel"><div class="panel-title"><h2>{{ tr("工资构成明细") }}</h2><span class="muted">{{ tr("周日为每周第一天") }}</span></div><div class="table-scroll"><table><thead><tr><th>{{ tr("老师") }}</th><th>{{ tr("币种") }}</th><th>{{ tr("录入天数") }}</th><th>{{ tr("完课工资") }}</th><th>{{ tr("时长工资") }}</th><th>{{ tr("半薪补偿") }}</th><th>{{ tr("晚间奖励") }}</th><th>{{ tr("人工调整") }}</th><th class="right">{{ tr("总工资") }}</th></tr></thead><tbody><tr v-for="r in report"><td><strong>{{ r.teacher.name }}</strong><small v-if="r.teacher.deletedAt" class="schedule-source">{{locale==='en'?'Deleted / resigned':'已删除 / 已离职'}}</small><small class="schedule-source">{{ tr(payModeLabel(r.teacher.payMode)) }}</small></td><td>{{ tr(r.teacher.currency) }}</td><td>{{ tr(r.days) }}</td><td>{{ tr(money(r.lesson,r.teacher.currency)) }}</td><td>{{ tr(money(r.hourlyPay,r.teacher.currency)) }}</td><td>{{ tr(money(r.compensation,r.teacher.currency)) }}</td><td>{{ tr(money(r.bonus,r.teacher.currency)) }}</td><td>{{ tr(money(r.adjustments,r.teacher.currency)) }}</td><td class="right salary">{{ tr(money(r.total,r.teacher.currency)) }}</td></tr></tbody></table></div><div v-if="!report.length" class="empty-state"><Wallet :size="30"/><h3>{{ tr("暂无汇总记录") }}</h3><p>{{ tr("先添加老师并在每日工作台录入完课数量。") }}</p></div><div class="table-footer">{{ tr("未录入的日期不按零完课自动计薪；导出的 Excel 包含汇总和每日明细两个工作表。") }}</div></section></template>
      <footer class="page-footer"><span>{{ tr("课时簿 · 体验课教务管理") }}</span><span>{{ tr("每个半小时，都值得认真记录。") }}</span></footer>
    </main>
  </div>
</div>
<div v-if="modal" class="modal-overlay" @click.self="modal=null"><section class="modal" :class="{wide:modal==='daily'||modal==='schedule'||modal==='dateSchedule'||modal==='importReview'}" role="dialog" aria-modal="true" :aria-label="tr(modal==='daily'?tr('每日记录'):tr('编辑信息'))"><LanguageSwitch class="modal-language"/><button class="close" :aria-label='tr("关闭")' @click="modal=null"><X :size="21"/></button>
  <template v-if="modal==='teacher'"><div class="eyebrow">NEW TEACHER</div><h2>{{ tr(editingTeacher?tr('编辑老师资料'):tr('添加老师')) }}</h2><p class="muted">{{ tr("填写基本信息，再设置每周固定排班。") }}</p><form @submit.prevent="saveTeacher"><div class="form-grid"><label>{{ tr("姓名") }}<input v-model="teacherForm.name" required :placeholder='tr("例如：张老师")'/></label><label>{{ tr("性别") }}<select v-model="teacherForm.gender"><option :value='"女"'>{{ tr("女") }}</option><option :value='"男"'>{{ tr("男") }}</option><option :value='"未提供"'>{{ tr("未提供") }}</option></select></label><label>{{ tr("科目") }}<input v-model="subjectInput" required/></label><label>{{ tr("币种") }}<select v-model="teacherForm.currency" required><option disabled value="">{{ tr("请选择币种") }}</option><option :value='"EGP"'>EGP</option><option :value='"JOD"'>JOD</option></select></label><label class="full">{{ tr("计薪方式") }}<select v-model="teacherForm.payMode"><option value="slot">{{ tr("按 slot：完课全薪，未完课半薪") }}</option><option value="hourly">{{ tr("按开放时长：全时薪，不享受晚间奖励") }}</option></select><small v-if="teacherForm.payMode==='hourly'">{{ tr("工资按有效开放总时长计算；完课数量仅用于统计，奖金与扣款仍可人工调整。") }}</small></label><label class="full">{{ tr("时薪") }}<input type="number" v-model="teacherForm.rate" :min="teacherForm.currency==='JOD'?0.001:0.01" :step="teacherForm.currency==='JOD'?0.001:0.01" required/><small>{{ tr(teacherForm.payMode==='hourly'?tr('有效开放半小时按时薪的一半全额计薪，不另算半薪补偿。'):tr('每个 slot 工资 = 时薪 ÷ 2')) }}</small></label></div><p v-if="error" class="error">{{ tr(error) }}</p><div class="modal-actions"><button v-if="editingTeacher" type="button" class="danger-button" @click="requestDelete"><Trash2 :size="15"/>{{locale==='en'?'Delete teacher':'删除老师'}}</button><button type="button" class="secondary" @click="modal=null">{{ tr("取消") }}</button><button class="primary">{{ tr(editingTeacher?tr('保存资料'):tr('保存老师')) }}</button></div></form></template>
  <template v-if="modal==='schedule'"><div class="eyebrow">WEEKLY AVAILABILITY</div><h2>{{ tr("设置固定排班") }}</h2><p class="muted">{{ tr("可以为同一天添加多个时间段，时间段不能重叠。") }}</p><label class="field">{{ tr("生效日期") }}<input type="date" v-model="effective"/></label><div class="schedule-editor"><div v-for="(r,i) in ranges" class="range-row"><select v-model="r.day"><option v-for="(day,d) in WEEKDAYS" :value="d">{{ tr(day) }}</option></select><input type="time" step="1800" v-model="r.start"/><span>{{ tr("至") }}</span><input type="time" step="1800" v-model="r.end"/><button class="icon-button" :aria-label='tr("移除时间段")' @click="ranges.splice(i,1)"><Trash2 :size="16"/></button></div></div><button class="secondary" @click="ranges.push({day:0,start:'16:00',end:'21:00'})"><Plus :size="16"/>{{ tr("添加时间段") }}</button><div class="info-bar">{{ tr("跨天排班请按两个日期分别记录。空排班版本表示暂停固定开放。尚未录入工资时，可以使用同一生效日期核对修正，修正前版本会保留。") }}</div><p v-if="error" class="error">{{ tr(error) }}</p><div class="modal-actions"><button class="secondary" @click="modal=null">{{ tr("取消") }}</button><button class="primary" @click="saveSchedule">{{ tr("保存新版本") }}</button></div></template>
  <template v-if="modal==='dateSchedule'"><div class="eyebrow">DATE-SPECIFIC AVAILABILITY</div><h2>{{ tr("指定日期排班") }}</h2><p class="muted">{{ tr(data.teachers.find(t=>t.id===scheduleTeacher)?.name) }} · {{ tr(dateScheduleDay) }} · {{ tr(WEEKDAYS[weekday(dateScheduleDay)]) }}{{ tr("。仅替换这一天的固定模板，不影响其他日期。") }}</p><div class="info-bar">{{ tr("每段时间按半小时设置。删除全部时段后保存，表示当天不开放，不会回退到固定排班。") }}</div><div class="schedule-editor"><div v-for="(r,i) in dateRanges" class="range-row"><input :aria-label='tr("当天开始时间")' type="time" step="1800" v-model="r.start"/><span>{{ tr("至") }}</span><input :aria-label='tr("当天结束时间")' type="time" step="1800" v-model="r.end"/><button class="icon-button" :aria-label='tr("移除当天时间段")' @click="dateRanges.splice(i,1)"><Trash2 :size="16"/></button></div></div><div class="date-schedule-tools"><button class="secondary" @click="dateRanges.push({start:'17:00',end:'21:00'})"><Plus :size="15"/>{{ tr("添加当天时间段") }}</button><button class="secondary" @click="copyLastWeek">{{ tr("沿用上周同日") }}</button></div><label class="field" style="margin-top:20px">{{ tr("排班备注") }}<input v-model="dateReason" :placeholder='tr("例如：本周五临时开放 17:00–21:00")'/></label><p class="muted" style="font-size:10px;line-height:1.8;margin-top:15px">{{ tr("该日期已录入工资时，请在每日记录中用异常调整，避免改动原始排班。临时排班与固定排班采用相同的工资规则。") }}</p><p v-if="error" class="error">{{ tr(error) }}</p><div class="modal-actions"><button v-if="data.teachers.find(t=>t.id===scheduleTeacher)?.dateSchedules?.[dateScheduleDay]" class="secondary" @click="restoreFixed">{{ tr("恢复当天固定模板") }}</button><button class="secondary" @click="modal=null">{{ tr("取消") }}</button><button class="primary" @click="saveOneDate">{{ tr("保存当天排班") }}</button></div></template>
  <template v-if="modal==='daily'"><div class="eyebrow">DAILY RECORD</div><h2>{{ selected.name }} <span class="modal-subdate">{{ tr(date) }} · {{ tr(WEEKDAYS[weekday(date)]) }}</span></h2><p class="muted">{{ tr(payModeLabel(selected.payMode)) }}{{ tr(" · 时薪 ") }}{{ tr(money(selected.rate,selected.currency)) }} {{ tr(selected.currency) }}{{ tr(" · 每个 slot ") }}{{ tr(money(selected.rate/2,selected.currency)) }} {{ tr(selected.currency) }}</p><div class="daily-editor"><div><label class="field">{{ tr("当天完课数量") }}<input type="number" min="0" :max="livePay?.slots.length" step="1" v-model="draft.completed"/><small>{{ tr("填写 0 表示已核对，当天没有完课。") }}{{ tr(selected.payMode==='hourly'?tr('完课数量仅作统计，不影响开放时长工资。'):'') }}</small></label><h3 class="editor-heading">{{ tr("时间异常 ") }}<span>{{ tr("先加时，再扣除请假 / 缺席 / 其他异常") }}</span></h3><div v-for="(e,i) in draft.exceptions" class="record-chip"><div><strong>{{ tr(kindName(e.kind)) }} · {{ tr(e.start) }}–{{ tr(e.end) }}</strong><small>{{ e.reason }}</small></div><button class="icon-button" :aria-label='tr("删除异常")' @click="draft.exceptions.splice(i,1)"><X :size="15"/></button></div><div class="exception-form"><select v-model="exception.kind"><option value="add">{{ tr("临时加时") }}</option><option value="leave">{{ tr("请假") }}</option><option value="other">{{ tr("异常扣除 slot") }}</option><option value="absent">{{ tr("老师缺席") }}</option></select><div class="inline-times"><input type="time" step="1800" v-model="exception.start"/><span>{{ tr("至") }}</span><input type="time" step="1800" v-model="exception.end"/></div><input v-model="exception.reason" :placeholder='tr("原因（必填）")'/><button class="secondary" @click="addException"><Plus :size="15"/>{{ tr("添加异常") }}</button></div><p class="muted" style="font-size:10px;line-height:1.8;margin-top:10px">{{ tr("暂不自动处理迟到。如需处理，可手动扣除受影响的 slot 并说明原因，或在下方录入调整金额。") }}</p><h3 class="editor-heading">{{ tr("奖金、罚款与人工调整") }}</h3><div v-for="(a,i) in draft.adjustments" class="record-chip"><div><strong>{{ tr(a.amount>0?'+':'') }}{{ tr(money(a.amount,selected.currency)) }} {{ tr(selected.currency) }}</strong><small>{{ a.reason }}</small></div><button class="icon-button" :aria-label='tr("删除调整")' @click="draft.adjustments.splice(i,1)"><X :size="15"/></button></div><div class="adjust-form"><input type="number" step="0.001" v-model="adjustment.amount" :placeholder='tr("正数奖金 / 负数扣款")'/><input v-model="adjustment.reason" :placeholder='tr("调整原因（必填）")'/><button class="secondary" @click="addAdjustment">{{ tr("添加") }}</button></div></div><aside class="pay-breakdown"><div class="pay-heading"><Wallet :size="19"/>{{ tr("工资明细") }}</div><template v-if="livePay"><div class="pay-line"><span>{{ tr("有效 slot") }}</span><strong>{{ tr(livePay.slots.length) }}{{ tr(" 个") }}</strong></div><div class="slot-preview"><span v-for="s in livePay.slots" :class="{evening:s>=1020&&s<1260}">{{ tr(clock(s)) }}</span></div><template v-if="livePay.payMode==='hourly'"><div class="pay-line"><span>{{ tr("计薪开放时长") }}<small>{{ tr(livePay.slots.length) }}{{ tr(" 个 slot ÷ 2") }}</small></span><strong>{{ tr(livePay.paidHours) }}{{ tr(" 小时") }}</strong></div><div class="pay-line"><span>{{ tr("开放时长工资") }}<small>{{ tr(livePay.paidHours) }} × {{ tr(money(selected.rate,selected.currency)) }} {{ tr(selected.currency) }}</small></span><strong>{{ tr(money(livePay.hourlyPay,selected.currency)) }}</strong></div><div class="pay-line"><span>{{ tr("完课统计") }}<small>{{ tr("仅记录，不影响工资") }}</small></span><strong>{{ tr(livePay.completed) }}{{ tr(" 节") }}</strong></div><div class="pay-line"><span>{{ tr("晚间奖励") }}<small>{{ tr("此计薪方式不适用") }}</small></span><strong>0.00</strong></div></template><template v-else><div class="pay-line"><span>{{ tr("完课工资") }}<small>{{ tr(livePay.completed) }} × {{ tr(money(livePay.slotRate,selected.currency)) }}</small></span><strong>{{ tr(money(livePay.lesson,selected.currency)) }}</strong></div><div class="pay-line"><span>{{ tr("未完课补偿") }}<small>{{ tr(livePay.remaining) }} × {{ tr(money(livePay.slotRate/2,selected.currency)) }}</small></span><strong>{{ tr(money(livePay.compensation,selected.currency)) }}</strong></div><div class="pay-line"><span>{{ tr("晚间奖励") }}<small>{{ tr(livePay.bonusHours) }}{{ tr(" 个完整小时 × 100 EGP") }}</small></span><strong>{{ tr(money(livePay.bonus,selected.currency)) }}</strong></div></template><div class="pay-line"><span>{{ tr("人工调整") }}</span><strong>{{ tr(money(livePay.adjustments,selected.currency)) }}</strong></div><div class="pay-total"><span>{{ tr("当日总工资") }}</span><strong>{{ tr(money(livePay.total,selected.currency)) }}<small>{{ tr(selected.currency) }}</small></strong></div></template><p v-else class="error">{{ tr("完课数量超出有效 slot，或时间记录无效。") }}</p><p class="breakdown-note">{{ tr(selected.payMode==='hourly'?tr('按有效开放总时长全额支付，完课数量不影响工资，不发晚间奖励。'):tr('绿色时间为晚间范围。奖励按连续完整小时计算，零散半小时不计奖励。')) }}</p></aside></div><p v-if="error" class="error">{{ tr(error) }}</p><div class="modal-actions"><button class="secondary" @click="modal=null">{{ tr("取消") }}</button><button class="primary" @click="saveDaily"><Check :size="17"/>{{ tr("保存每日记录") }}</button></div></template>
  <template v-if="modal==='importReview'"><div class="eyebrow">SOURCE RECONCILIATION</div><h2>{{ tr("导入核对") }}</h2><p v-if="data.imports?.find(i=>i.id===seed.id)?.conflicts.length" class="error">{{ tr("以下同名同科目老师已存在，未覆盖其原排班：") }}{{ tr(data.imports.find(i=>i.id===seed.id).conflicts.join('、')) }}</p><div class="rules-list"><p v-for="note in seed.notes">{{ tr(note) }}</p></div><div class="table-scroll" style="max-height:380px"><table><thead><tr><th>{{ tr("原表位置") }}</th><th>{{ tr("科目 / 星期 / 时间") }}</th><th>{{ tr("原单元格内容") }}</th></tr></thead><tbody><tr v-for="c in seed.cells"><td>slot!{{ tr(c.cell) }}</td><td>{{ tr(c.subject) }} · {{ tr(WEEKDAYS[c.day]) }} · {{ tr(clock(c.start)) }}</td><td style="white-space:normal;min-width:200px">{{ c.raw }}</td></tr></tbody></table></div><div class="modal-actions"><button class="primary" @click="modal=null">{{ tr("关闭核对") }}</button></div></template>
  <template v-if="modal==='settings'"><div class="eyebrow">RULES & DATA</div><h2>{{ tr("规则与数据") }}</h2><div class="rules-list"><p><strong>{{ tr("按 slot 计薪") }}</strong><br>{{ tr("每个 slot 为 30 分钟，整点或半点开始。完课按时薪 ÷ 2 支付，剩余有效 slot 按此金额的 50% 补偿。EGP 和 JOD 老师均适用。") }}</p><p><strong>{{ tr("按开放时长计薪") }}</strong><br>{{ tr("有效开放总时长 × 时薪；完课仅作统计，不另算半薪补偿，也不享受晚间奖励。Dalia Bassem 已设置为此方式，270 EGP / 小时。") }}</p><p><strong>{{ tr("晚间奖励 · 已确认") }}</strong><br>{{ tr("EGP 老师每天 17:00–21:00，每段连续开放时间按完整小时奖励 100 EGP；不跨时间段凑满一小时。JOD 老师与按开放时长计薪的老师无晚间奖励。") }}</p><p><strong>{{ tr("每周与指定日期排班") }}</strong><br>{{ tr("周日到周四以固定排班为主；周五、周六可按每周具体日期安排，也支持固定模板。指定日期排班仅替换当天的固定模板，之后再处理加时和请假等异常。") }}</p><p><strong>{{ tr("时间异常") }}</strong><br>{{ tr("临时加时计入可用时间；请假和缺席移除相应 slot，不计基础工资及晚间奖励。所有异常须记录原因。") }}</p><p><strong>{{ tr("迟到处理") }}</strong><br>{{ tr("暂不单独记录或自动扣除迟到。需要处理时，由运营手动添加异常扣除 slot，或填写人工调整金额与原因。") }}</p><p><strong>{{ tr("数据保存") }}</strong><br>{{ tr("系统通过同一个网址自动连接 Supabase，无需访问码。浏览器保留本机备份；以页面同步状态为准。") }}</p></div><div class="modal-actions"><button class="secondary" @click="backup"><Download :size="15"/>{{ tr("下载数据备份") }}</button><button v-if="teachers.length===1&&data.teachers[0].id===demoId" class="secondary" @click="clearDemo">{{ tr("清除示例") }}</button><button class="primary" @click="modal=null">{{ tr("知道了") }}</button></div></template>
  <template v-if="modal==='deleteTeacher'"><div class="eyebrow">DELETE TEACHER</div><h2>{{locale==='en'?'Delete teacher':'删除老师'}}</h2><p class="muted">{{data.teachers.find(t=>t.id===editingTeacher)?.name}}</p><div class="info-bar">{{locale==='en'?'The teacher will be removed from active profiles, schedules and daily entry. Historical payroll and recorded lessons will remain available in Payroll Summary. This change will sync to everyone.':'删除后，该老师将从当前老师档案、课表和每日录入列表中移除。历史工资及已录入的完课记录会保留在工资汇总中。此操作会同步给所有使用者。'}}</div><label class="field">{{locale==='en'?'Enter the full teacher name to confirm':'输入完整的老师姓名确认删除'}}<input v-model="deleteName" autocomplete="off"/></label><p v-if="error" class="error">{{tr(error)}}</p><div class="modal-actions"><button class="secondary" @click="modal='teacher';error=''">{{tr('取消')}}</button><button class="danger-button" :disabled="deleteName.trim()!==data.teachers.find(t=>t.id===editingTeacher)?.name" @click="confirmDelete">{{locale==='en'?'Confirm deletion':'确认删除'}}</button></div></template>
</section></div>
<div v-if="notice" class="toast"><Check :size="17"/>{{ tr(notice) }}</div>
</template>
